const CACHE='ruay-home-v49';const ASSETS=['./','./index.html','./style.css?v=49','./app.js?v=49','./core.js','./backup.js?v=49','./firebase-config.js','./firebase-backup.js?v=49','./comparison.js','./history.js?v=49','./history.json?v=49','./calendar-clock.js','./prices.js','./price-config.js','./price-loader.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(url=>new Request(url,{cache:'reload'})))).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin)return;if(u.pathname.endsWith('/prices.json')){e.respondWith(fetch(e.request,{cache:'no-store'}));return;}e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request)))});